list_aliases.code:
final response = await client.aliases.listAliases(queryParams: {'limit': 20});
final aliases = (response.map as Map)['aliases'] as List;
for (final alias in aliases) {
  print('${(alias as Map)['id']} ${alias['alias']}');
}

create_alias.code:
final response = await client.aliases.createAlias({
  'alias': 'shop.example.com',
});
final alias = (response.map as Map)['alias'] as Map;
print('${alias['id']} ${alias['alias']}');
